import assert from "node:assert/strict";
import { readFileSync,statfsSync } from "node:fs";
import { join } from "node:path";
import { draft,actualOpening } from "./runtime/opening";
import { play } from "./runtime/play";
import { shieldFormation } from "./geometry";
import { withScopedAIEnvironment } from "./runtime/sources/common/src/simulation/v0_8_a13_search";
import { seatEnvName } from "./runtime/sources/common/src/ai/seat_env";
import { P,read,save,digest,sha,seals } from "./io";
const reg=seals();
const [host,workerText,workersText,stage="screen"]=process.argv.slice(2), worker=Number(workerText),workers=Number(workersText);
const cases=read("cases.json");
const all=cases.flatMap((task:any,index:number)=>[0,1].map(seat=>({task,index,seat,id:`${task.id}-s${seat}`})));
const jobs=stage==="smoke"?all.filter((j:any)=>j.index===0):stage==="cold"?all.filter((j:any)=>[0,36,72].includes(j.index)&&j.seat===0):all;
const modes=["native","abomination","formation_guard"];
for(let j=worker;j<jobs.length;j+=workers){
    const job=jobs[j], rows:any={};
    const rotated=modes.map((_m,i)=>modes[(i+job.index+job.seat)%modes.length]);
    for(const mode of rotated){
        assert(Date.now()<reg.cutoffUnix*1000,"Fixed study cutoff");
        const fs=statfsSync(P);assert(fs.bavail*fs.bsize>2*1024**3);
        const drafted=draft(job.task,mode==="native"?"native":"abomination");
        assert(drafted.interventions[0].counterpickQualified);
        const opening=actualOpening(drafted,job.seat?job.task.reverseSetup:job.task.setup,!!job.seat,0,false,mode.startsWith("formation")?shieldFormation:undefined);
        const guard=mode.endsWith("guard");
        const result=withScopedAIEnvironment({V08_ABOMINATION_GUARD_LEFT:"0",V08_ABOMINATION_GUARD_RIGHT:"0",[seatEnvName("V08_ABOMINATION_GUARD",opening.candidateTeam)]:guard?"1":"0"},()=>play(opening,job.task.evalFutures[0]));
        const row={...result,opening,drafted,job,mode,host,registrationSha256:sha(readFileSync(join(P,"registration.json")))};
        save(`${stage}/${job.id}-${mode}.json.gz`,row);
        assert(result.qualityPassed,result.error);
        rows[mode]=row;
        if(stage==="cold"){
            const prior=read(`screen/${job.id}-${mode}.json.gz`);
            for(const field of ["opening","drafted","result","turns","events","health"])assert.equal(digest(row[field]),digest(prior[field]),field);
        }
    }
    assert.equal(digest(rows.abomination.opening.setupReceipts),digest(rows.formation_guard.opening.setupReceipts));
    const enemy=3-rows.abomination.candidateTeam;
    assert.equal(digest(rows.abomination.opening.teams[enemy]),digest(rows.formation_guard.opening.teams[enemy]));
    save(`${stage}/complete-${job.id}.json`,{qualityPassed:true,job,host});
    console.log(JSON.stringify({stage,host,worker,completed:job.id}));
}

