import assert from "node:assert/strict";
import { getAuraCellKeyMembershipForBody } from "./runtime/sources/common/src/effects/effect_helper";
import { isV08BacklineProtectionBeneficiary, v08BacklineWardValue } from "./runtime/sources/common/src/ai/versions/v0_8_backline_protector";
const key = (p: any) => (p.x << 4) | p.y;
const distance = (a: any, b: any) => Math.abs(a.x - b.x) + Math.abs(a.y - b.y);
export function shieldFormation(session: any, team: number, units: any[], baseline: any[]) {
    // Only own accepted units, own paid zone and public terrain are used. No enemy positions or kits.
    const legal: Set<number> = session.allowedPlacementHashesByTeam.get(team);
    const cells = [...legal].sort((a,b) => a-b).map(k => ({x:k >> 4,y:k & 15}));
    const body = (i: number, p: any) => session.aiFootprintForCell(units[i], p);
    const abom = units.findIndex(u => u.getName() === "Abomination");
    if(abom < 0) return {bodies:units.map(u=>[u.getName(),u.getAmountAlive(),u.getFootprintWidth(),u.getFootprintHeight()]),positions:baseline};
    const wards = units.map((u,i) => ({u,i})).filter(({u,i}) => i !== abom && isV08BacklineProtectionBeneficiary(u))
        .sort((a,b) => v08BacklineWardValue(b.u)-v08BacklineWardValue(a.u) || a.i-b.i);
    const range = units[abom].getAuraEffect("Flesh Shield").getRange() + session.fightProperties.getAdditionalAuraRangePerTeam(team);
    const covered = (positions: any[]) => {
        const area = getAuraCellKeyMembershipForBody(session.grid.getSettings(), body(abom,positions[abom]),range);
        return wards.reduce((sum,{u,i}) => sum + (body(i,positions[i]).some((p:any)=>area.has(key(p))) ? v08BacklineWardValue(u) : 0),0);
    };
    const movable = new Set([abom,...wards.map(w=>w.i)]), fixed = new Set<number>();
    units.forEach((_u,i) => {if(!movable.has(i)) body(i,baseline[i]).forEach((p:any)=>fixed.add(key(p)));});
    let best = structuredClone(baseline), bestValue = covered(best), bestDistance = 0;
    const fits = (i:number,p:any,occupied:Set<number>) => body(i,p).every((c:any)=>legal.has(key(c)) && !occupied.has(key(c)));
    for (const anchor of cells) {
        if (!fits(abom,anchor,fixed)) continue;
        const positions = structuredClone(baseline), occupied = new Set(fixed);
        positions[abom] = anchor;
        body(abom,anchor).forEach((p:any)=>occupied.add(key(p)));
        const area = getAuraCellKeyMembershipForBody(session.grid.getSettings(),body(abom,anchor),range);
        let feasible = true;
        for (const {i} of wards) {
            const options = cells.filter(p=>fits(i,p,occupied));
            options.sort((a,b)=>Number(body(i,b).some((p:any)=>area.has(key(p))))-Number(body(i,a).some((p:any)=>area.has(key(p)))) || distance(a,baseline[i])-distance(b,baseline[i]) || key(a)-key(b));
            if (!options.length) { feasible=false;break; }
            positions[i]=options[0]; body(i,options[0]).forEach((p:any)=>occupied.add(key(p)));
        }
        if (!feasible) continue;
        const value=covered(positions), moved=positions.reduce((n:number,p:any,i:number)=>n+distance(p,baseline[i]),0);
        if(value>bestValue || (value===bestValue && moved<bestDistance)){best=positions;bestValue=value;bestDistance=moved;}
    }
    return { bodies: units.map(u=>[u.getName(),u.getAmountAlive(),u.getFootprintWidth(),u.getFootprintHeight()]), positions:best };
}

