import assert from "node:assert/strict";
import { draft } from "./runtime/opening";
import { creatureInfo } from "./runtime/sources/common/src/ai/setup/creature_score";
import { read, save, digest } from "./io";
const counts=new Map<string,number>(), selected:any[]=[], examined:any[]=[];
for(const task of read("manifest.json").pool){
    const stratum=`${task.map}/${task.d1}/${task.d2}/${task.pickOrder}`;
    if((counts.get(stratum) ?? 0) >= 2)continue;
    const d=draft(task), x=d.interventions[0];
    examined.push({id:task.id,eligible:!!x?.counterpickQualified});
    if(!x?.counterpickQualified)continue;
    const a=draft(task,"abomination"), b=draft(task,"alternative");
    for(const q of [a,b]) assert.equal(digest(q.interventions[0].context),digest(x.context));
    const info=(ids:number[])=>ids.map(id=>creatureInfo(id));
    selected.push({...task, offer:x, nativeOffers:d.interventions, ownPublicInfo:info(x.context.ownCreatureIds), knownEnemyInfo:info(x.context.knownOpponentCreatureIds)});
    counts.set(stratum,(counts.get(stratum) ?? 0)+1);
}
if(selected.length!==108){console.log(JSON.stringify({incompleteFamilies:selected.length,missing:[...new Set(read("manifest.json").pool.map((t:any)=>`${t.map}/${t.d1}/${t.d2}/${t.pickOrder}`))].filter((s:any)=>(counts.get(s)??0)<2).map((s:any)=>({stratum:s,have:counts.get(s)??0}))}));}
assert.equal(selected.length,108);
save("cases.json",selected);
save("selection.json",{families:selected.length,examined,noCombatOutcomesOpened:true,rule:"First two public legal Abomination offers per map/doctrine pair/pick order with at least two revealed ranged units, no revealed magic-damage unit and at least two own ranged/caster units; no outcome filtering"});
console.log(JSON.stringify({families:selected.length,examined:examined.length,nativeAbomination:selected.filter(x=>x.offer.native===41).length}));

